```cpp
inline int32_t zOrder(const double x_, const double y_) {
    // coords are transformed into non-negative 15-bit integer range
    int32_t x = static_cast<int32_t>((x_- minX) * invSize);
    int32_t y = static_cast<int32_t>((y_- minY) * invSize);
    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;
    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;
    return x | (y << 1);
}
```

static_cast<int32_t> of f64 truncates toward zero; Rust `as i32` also truncates toward zero. Values are non-negative here. Good.

sortList (merge sort on z, circular):

```cpp
Node* sortList(Node* list) {
    Node* inSize = list;
    int numMerges, pSize, qSize, insize = 1;
    while (true) {
        Node* p = inSize;
        inSize = nullptr;
        Node* tail = inSize;
        numMerges = 0;
        while (p) {
            numMerges++;
            Node* q = p;
            pSize = 0;
            for (int i = 0; i < insize; i++) {
                pSize++;
                q = q->nextZ;
                if (!q) break;
            }
            qSize = insize;
            while (pSize > 0 || (qSize > 0 && q)) {
                Node* e;
                if (pSize == 0) {
                    e = q; q = q->nextZ; qSize--;
                } else if (qSize == 0 || !q) {
                    e = p; p = p->nextZ; pSize--;
                } else if (p->z <= q->z) {
                    e = p; p = p->nextZ; pSize--;
                } else {
                    e = q; q = q->nextZ; qSize--;
                }
                if (tail) tail->nextZ = e; else inSize = e;
                e->prevZ = tail;
                tail = e;
            }
            p = q;
        }
        tail->nextZ = nullptr;
        if (numMerges <= 1) return inSize;
        insize *= 2;
    }
}
```

That's the standard linked-list merge sort.

