Node* linkedList(const Ring& points, bool clockwise) {
    Node* last = nullptr;
    if (clockwise == (signedArea(points) > 0)) {
        for (int i = 0; i < (int)points.size(); i++) last = insertNode(vertices + i, points[i][0], points[i][1], last);
    } else {
        for (int i = points.size() - 1; i >= 0; i--) last = insertNode(vertices + i, points[i][0], points[i][1], last);
    }
    if (last && equals(last, last->next)) {
        removeNode(last);
        last = last->next;
    }
    return last;
}
