pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut e = Earcut { nodes: Vec::new(), indices: Vec::new(), inv_size: 0.0, min_x: 0.0, min_y: 0.0 };
    e.run(polygon);
    e.indices
}

impl Earcut {
    fn run(&mut self, polygon: &[Vec<[f64; 2]>]) {
        if polygon.is_empty() { return; }
        let len = polygon[0].len();
        let threshold = 80usize;

        if len > threshold {
            // bbox over all points of outer ring
            let mut min_x = polygon[0][0][0];
            let mut min_y = polygon[0][0][1];
            let mut max_x = min_x;
            let mut max_y = min_y;
            for p in &polygon[0][1..] {
                min_x = min_x.min(p[0]);
                min_y = min_y.min(p[1]);
                max_x = max_x.max(p[0]);
                max_y = max_y.max(p[1]);
            }
            self.min_x = min_x;
            self.min_y = min_y;
            let mut inv = (max_x - min_x).max(max_y - min_y);
            inv = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
            self.inv_size = inv;
        }

        let outer = self.linked_list(&polygon[0], true);
        if outer == NIL { return; }
        if self.nodes[outer].prev == self.nodes[outer].next { return; }

        if polygon.len() > 1 {
            self.eliminate_holes(polygon, outer);
            // outer may have changed; note eliminateHoles returns void in C++, outerNode reused
        }

        if len > threshold {
            // z-order all nodes and sort
            let mut cur = self.nodes[outer].next;
            while cur != outer {
                let (x, y) = (self.nodes[cur].x, self.nodes[cur].y);
                self.nodes[cur].z = self.z_order(x, y);
                self.nodes[cur].prev_z = self.nodes[cur].prev;
                self.nodes[cur].next_z = self.nodes[cur].next;
                cur = self.nodes[cur].next;
            }
            let (x, y) = (self.nodes[outer].x, self.nodes[outer].y);
            self.nodes[outer].z = self.z_order(x, y);
            self.nodes[outer].prev_z = self.nodes[outer].prev;
            self.nodes[outer].next_z = self.nodes[outer].next;
            let head = self.sort_list(outer);
            self.earcut_linked(head, 0);
        } else {
            self.earcut_linked(outer, 0);
        }
    }
}
