Now write sort_list (merge sort):

```rust
fn sort_list(&mut self, list: usize) -> usize {
    let mut in_size: usize = NIL;
    let mut insize = 1usize;
    let mut list = list;
    loop {
        let mut p = list;
        in_size = NIL;
        let mut tail = NIL;
        let mut num_merges = 0;
        while p != NIL {
            num_merges += 1;
            let mut q = p;
            let mut p_size = 0;
            for _ in 0..insize {
                p_size += 1;
                q = self.nodes[q].next_z;
                if q == NIL { break; }
            }
            let mut q_size = insize;
            while p_size > 0 || (q_size > 0 && q != NIL) {
                let e;
                if p_size == 0 {
                    e = q;
                    q = self.nodes[q].next_z;
                    q_size -= 1;
                } else if q_size == 0 || q == NIL {
                    e = p;
                    p = self.nodes[p].next_z;
                    p_size -= 1;
                } else if self.nodes[p].z <= self.nodes[q].z {
                    e = p;
                    p = self.nodes[p].next_z;
                    p_size -= 1;
                } else {
                    e = q;
                    q = self.nodes[q].next_z;
                    q_size -= 1;
                }
                if tail != NIL {
                    self.nodes[tail].next_z = e;
                } else {
                    in_size = e;
                }
                self.nodes[e].prev_z = tail;
                tail = e;
            }
            p = q;
        }
        self.nodes[tail].next_z = NIL;
        if num_merges <= 1 {
            return in_size;
        }
        list = in_size;
        insize *= 2;
    }
}
```

This matches the standard Simon Tatham merge sort as used in earcut. 

